def norm(v,c):
    if v is None:return ""
    if isinstance(v,(datetime,date)):return v.strftime("%Y-%m-%d")
    if isinstance(v,time):return v.strftime("%H:%M:%S")
    if isinstance(v,float) and v.is_integer():return int(v)
    return v
wb=load_workbook(SRC,read_only=True,data_only=True);ws=wb["진행중"] if "진행중" in wb.sheetnames else wb[wb.sheetnames[0]]
records=[]
for r in range(4,ws.max_row+1):
    if not str(ws.cell(r,4).value or "").strip():continue
    records.append([norm(ws.cell(r,c).value,c) for c in cols]+[r])
wb.close()
meta={"generatedAt":datetime.now().strftime("%Y-%m-%d"),"source":SRC.name,"privacy":"공개용: 담당자/연락처/금액/중요메모 제외","recordCount":len(records),"headers":headers,"cols":cols,"records":records}
OUT.write_text("window.PUBLIC_SITE_DATA="+json.dumps(meta,ensure_ascii=False,separators=(",",":"))+";\n",encoding="utf-8")
